  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Tailler l''agneau en petits morceaux de deux centimètres et les faire revenir dans l''huile au fond d''une grande marmite, avec l''oignon haché fin, jusqu''à ce que la viande soit colorée et l''oignon translucide. Des morceaux petits, et non des cubes de ragoût : dans une chorba la viande se mange à la cuillère, avec le bouillon, et ne se coupe pas au couteau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Ajouter la cannelle, le poivre et le concentré de tomate, et remuer deux minutes à feu moyen jusqu''à ce que le concentré fonce et sente le grillé. Ce court passage sur le feu retire au concentré son goût métallique de boîte ; versé directement dans l''eau, il le garde tout au long de la cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Verser les tomates concassées et laisser réduire cinq minutes, puis mouiller de toute l''eau, ajouter les pois chiches égouttés et porter à frémissement. Écumer la mousse grise qui monte pendant les premières minutes : c''est elle qui trouble le bouillon et lui donne un arrière-goût de suif.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Couvrir et laisser cuire quarante minutes à petits bouillons. La viande doit se défaire sous la cuillère avant que le moindre légume n''entre dans la marmite ; ajoutés plus tôt, les légumes seraient en purée quand l''agneau serait tout juste tendre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter alors les carottes en rondelles et les pommes de terre en dés, cuire quinze minutes, puis les courgettes en dés et cuire encore dix minutes. Cet échelonnement est ce qui fait qu''une chorba a des légumes reconnaissables et non un fond de purée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Jeter les vermicelles dans le bouillon bouillant et compter trois à quatre minutes, pas davantage. Ils continuent de gonfler dans la soupe chaude après le feu coupé : cuits à point dans la marmite, ils auront tout bu au moment de servir et il ne restera plus de bouillon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Couper le feu, saler, puis jeter la coriandre et la menthe ciselées et couvrir cinq minutes. Les herbes s''infusent sans cuire : bouillies, elles noircissent et perdent en une minute ce qui distingue cette soupe d''un potage à l''agneau. Servir très chaud, avec un quartier de citron pour qui le veut.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-022', 'recipe_family', 'Chorba algérienne',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-022', 'missing_required_count', v_missing), 'open');
  END IF;

