  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Chorba frik : 200 g de blé vert concassé rincé à la place des vermicelles, avec ras el-hanout et menthe sèche (chefsimon)','Chorba tunisienne : côtelettes d''agneau, pâtes courtes, quatre-épices et piment doux, sans coriandre fraîche (750g)','Au poulet : un demi-blanc de poulet à la place de l''agneau, avec curcuma et paprika (chefsimon)','Au céleri branche, deux branches taillées fin avec les carottes (marmiton, deux pages)','Enrichie de blé concassé à la place des vermicelles, à quantité égale (marmiton)']::text[]) AS variant(name);

