     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-022","variants":["Chorba frik : 200 g de blé vert concassé rincé à la place des vermicelles, avec ras el-hanout et menthe sèche (chefsimon)","Chorba tunisienne : côtelettes d''agneau, pâtes courtes, quatre-épices et piment doux, sans coriandre fraîche (750g)","Au poulet : un demi-blanc de poulet à la place de l''agneau, avec curcuma et paprika (chefsimon)","Au céleri branche, deux branches taillées fin avec les carottes (marmiton, deux pages)","Enrichie de blé concassé à la place des vermicelles, à quantité égale (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-022', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('81d63bd2771e84b98998a243e26a2d00'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"brothy_umami","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":1,"pungency":2,"richness":2,"freshness":3,"intensity":3},"dominant_flavors":["agneau","coriandre fraîche","tomate","cannelle"],"aroma_families":["coriandre","cannelle","tomate_cuite","agneau"],"target_textures":["bouillon_clair","viande fondante","légumes fondants"],"signature_ingredients":["Épaule d''agneau crue","Coriandre fraîche","Vermicelle fin sec"],"identity_guardrails":["Coriandre fraîche et menthe jetées hors du feu : ce sont elles qui font l''algéroise, et bouillies elles noircissent","La viande cuit quarante minutes seule avant les légumes, sinon ceux-ci se défont","Vermicelles trois à quatre minutes seulement — ils continuent de gonfler hors du feu et boivent tout le bouillon","Le concentré de tomate se fait revenir avant d''être mouillé, sans quoi il garde son goût de boîte"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Msemen', 'msemen', 'Maroc', 'Maroc',
     'meal', 'pain plat', 'named_traditional_dish', 'nutty_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Msemen', 'Galette feuilletée de farine et de semoule, pliée en carré et cuite à la poêle', ds.id, 'VAR-023',
    'Myko', 'editorial', 6, 20, 20, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '7d1a87e6ca58f4a235152f7f77675dc3',
    '{"sweet":1,"salty":2,"acidic":0,"bitter":0,"umami":1,"heat":0,"pungency":0,"richness":4,"freshness":0,"intensity":2}'::jsonb, ARRAY['semoule grillée','beurre','pâte cuite']::text[],
    ARRAY['beurre','céréale grillée','pain grillé']::text[], ARRAY['feuilletage souple','croûte croustillante','moelleux']::text[],
