     'finition', true, 14);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Tailler le bœuf en cubes de trois centimètres, les couvrir du bouillon froid et porter lentement à frémissement. Écumer soigneusement la mousse grise pendant le premier quart d''heure : c''est elle qui trouble le bouillon, et dans une soupe dont la couleur est l''argument principal, un bouillon terne se voit tout de suite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Laisser cuire une heure à couvert et à petits frémissements, jusqu''à ce que la viande cède sous la fourchette. Une ébullition franche resserre les fibres et fait une viande dure dans un bouillon gras : le bortsch se cuit à la surface juste tremblante.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pendant ce temps, râper la betterave crue à la grosse grille et la faire revenir dix minutes dans l''huile avec l''oignon émincé, le concentré de tomate et le vinaigre. C''est l''étape qui décide de la couleur : l''acide fixe le pigment de la betterave, qui vire au brun quand il cuit longtemps en milieu neutre. Sans vinaigre à ce moment-là, le bortsch finit terre de Sienne.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter au bouillon les pommes de terre en dés et les carottes en rondelles, cuire quinze minutes, puis le chou finement émincé et cuire dix minutes de plus. Le chou en dernier : il passe de croquant à filandreux en un quart d''heure et c''est lui qui donne au bortsch sa mâche.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser enfin la betterave revenue avec son jus dans la marmite et laisser dix minutes à feu doux, sans faire bouillir. Elle entre en dernier et ne bout pas : c''est la seconde condition de la couleur, et c''est aussi pourquoi une betterave déjà cuite, si l''on en emploie, se contente de ces dix minutes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Saler, poivrer, goûter et rectifier l''acidité — le bortsch doit être franchement acidulé, sensiblement plus que ce que l''on croit en le goûtant chaud. Couper le feu, jeter le persil ciselé, couvrir et laisser reposer une demi-heure : la soupe se stabilise et le goût s''arrondit.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Servir très chaud, avec une cuillerée de crème aigre déposée dans chaque assiette pour qui en veut. La crème se met dans l''assiette et non dans la marmite : elle tranche à l''ébullition, et le reste de la soupe se conserve mieux sans elle.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-026', 'recipe_family', 'Bortsch',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-026', 'missing_required_count', v_missing), 'open');
  END IF;

