  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Bœuf Stroganoff', 'Lamelles de bœuf sautées aux champignons dans une sauce à la crème et au vin blanc', ds.id, 'VAR-027',
    'Myko', 'editorial', 4, 15, 25, 'facile',
    NULL, NULL,
    'B', 'candidate', 'a0adc1210872aa16fcc0fe955c852188',
    '{"sweet":2,"salty":3,"acidic":3,"bitter":0,"umami":4,"heat":1,"pungency":3,"richness":4,"freshness":1,"intensity":4}'::jsonb, ARRAY['moutarde','crème','champignon','bœuf saisi']::text[],
    ARRAY['moutarde','champignon_terreux','lactée','paprika']::text[], ARRAY['sauce_nappante','tendre','champignon_fondant']::text[],
    ARRAY['Bœuf à griller cru, en fines lamelles','Moutarde de Dijon','Crème fraîche épaisse']::text[], ARRAY['Le bœuf se taille en lanières et se saisit en plusieurs fois : entassé, il bout et durcit sans retour','La moutarde entre hors ébullition et en dernier — bouillie, elle perd tout son piquant','Ce n''est jamais un plat de viande hachée ni de bœuf à mijoter : la cuisson totale de la viande est de deux minutes','Les champignons se sautent à sec et sans sel avant la sauce, sinon ils rendent leur eau dedans']::text[],
    ARRAY['saisie','sauté à feu vif','singer','déglaçage','réduction','liaison à la crème']::text[], ARRAY['À la crème aigre, 80 à 125 ml, ou à la crème additionnée de jus de citron (chefsimon)','Au gingembre frais râpé, avec du fond de veau à la place du bouillon (marmiton)','De luxe : viande à fondue, six oignons blancs, 500 g de champignons, trois cuillerées à soupe de moutarde et un demi-litre de crème (marmiton)','Sans farine, liaison à la fécule de maïs pour une version sans gluten (chefsimon)','Avec une pincée de sucre pour corriger l''acidité de la moutarde et du vin (marmiton)']::text[], ARRAY['lait','gluten','moutarde']::text[],
    'Se garde 2 jours au réfrigérateur, mais la viande se raffermit au réchauffage — c''est un plat qui se mange le jour même. Réchauffer à feu très doux sans jamais faire bouillir, la crème et la moutarde ne le supportant pas. Ne se congèle pas : la sauce à la crème tranche et les lanières deviennent fibreuses. La sauce seule, sans viande, se prépare la veille et se garde 3 jours ; il ne reste alors que deux minutes de poêle le soir venu.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
