  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-028', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Au sarrasin : 150 g de farine de blé et 100 g de farine de sarrasin, forme absente du catalogue et donc non écrite ici (chefsimon)','À la levure chimique : 8 g pour six, sans temps de pousse (marmiton, chefsimon)','Au yaourt : 200 g de yaourt épais à la place d''une partie du lait, avec de l''huile d''olive plutôt que du beurre (chefsimon, marmiton)','Garnis de gruyère râpé et de jambon blanc, ou de bacon, cuits dans la pâte (750g)','En version apéritive : louches de la taille d''une cuillère à café, une douzaine de plus par fournée (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-028","variants":["Au sarrasin : 150 g de farine de blé et 100 g de farine de sarrasin, forme absente du catalogue et donc non écrite ici (chefsimon)","À la levure chimique : 8 g pour six, sans temps de pousse (marmiton, chefsimon)","Au yaourt : 200 g de yaourt épais à la place d''une partie du lait, avec de l''huile d''olive plutôt que du beurre (chefsimon, marmiton)","Garnis de gruyère râpé et de jambon blanc, ou de bacon, cuits dans la pâte (750g)","En version apéritive : louches de la taille d''une cuillère à café, une douzaine de plus par fournée (chefsimon)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-028', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('a1c1f17cba6317a8217e11fa19d073ea'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_delicate","scores":{"sweet":2,"salty":2,"acidic":2,"bitter":0,"umami":1,"heat":0,"pungency":0,"richness":3,"freshness":0,"intensity":2},"dominant_flavors":["lait","beurre","levure"],"aroma_families":["lacté","beurre","pain grillé"],"target_textures":["moelleux","alvéolé","dessus_doré"],"signature_ingredients":["Farine de blé T55","Lait entier","Levure boulangère fraîche"],"identity_guardrails":["Une heure de pousse à la levure de boulanger : sans elle, c''est une crêpe épaisse et non un blini","Les blancs montés s''incorporent au dernier moment — ils retombent en un quart d''heure","On retourne quand la surface est criblée de trous ouverts, pas avant","Les blinis cuits s''empilent sous un linge : à l''air, ils croûtent en dix minutes"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Koulibiac de saumon', 'koulibiac de saumon', 'Russie', 'Russie',
     'meal', 'tourte', 'named_traditional_dish', 'creamy_delicate',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Koulibiac de saumon', 'Tourte feuilletée garnie de saumon, de riz, d''épinards et de champignons', ds.id, 'VAR-029',
    'Myko', 'editorial', 6, 30, 60, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'a5d46843d7bbca8ed862c964b9fa423e',
    '{"sweet":1,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":0,"richness":4,"freshness":2,"intensity":3}'::jsonb, ARRAY['saumon','aneth','beurre','champignon']::text[],
    ARRAY['marin','herbacé','beurre','champignon']::text[], ARRAY['feuilletage croustillant','chair_moelleuse','contraste_léger']::text[],
    ARRAY['Pavé de saumon cru, sans peau','Pâte feuilletée crue','Aneth frais']::text[], ARRAY['Tout ce qui entre dans la tourte doit être froid et sec : un riz tiède ou des épinards mal pressés détrempent le fond','Les œufs durs se rangent en file au centre — c''est la tranche qui fait reconnaître un koulibiac','Une cheminée dans le couvercle, sinon la vapeur fait éclater la pâte sur le côté','Un quart d''heure de repos sur grille avant la découpe, sans quoi la tranche s''effondre']::text[],
    ARRAY['refroidissement','pressage','sauté à sec','montage','soudage','cuisson au four','repos']::text[], ARRAY['Sauce d''accompagnement : 40 cl de crème liquide réduite avec le jus d''un citron, servie à part (chefsimon, 750g)','Aux épinards seuls, sans riz : 1 kg d''épinards frais et 800 g de saumon pour quatre, avec des graines de sésame sur la dorure (marmiton)','Au fenouil : 400 g de fenouil émincé à la place des champignons (chefsimon)','Au comté : 150 g râpés répartis sur le riz (750g)','Aux œufs de caille, douze pièces à la place des trois œufs durs (chefsimon)','Saumon poché au court-bouillon et au vin blanc avant montage, avec cerfeuil et ciboulette (marmiton)']::text[], ARRAY['gluten','poisson','œuf','lait']::text[],
    'Se garde 3 jours au réfrigérateur et se réchauffe par tranches, 12 minutes à 190 °C sur une grille — le micro-ondes rend le feuilletage mou. Se mange aussi froid, en tranche épaisse, ce qui est un usage russe. Se congèle 2 mois cru et monté, sans dorure : on l''enfourne alors sans décongélation en ajoutant vingt-cinq minutes et en dorant au sortir du congélateur. Le riz, les œufs durs et les épinards pressés se préparent la veille et se gardent séparément 2 jours.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
