  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-029', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('a5d46843d7bbca8ed862c964b9fa423e'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_delicate","scores":{"sweet":1,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":0,"richness":4,"freshness":2,"intensity":3},"dominant_flavors":["saumon","aneth","beurre","champignon"],"aroma_families":["marin","herbacé","beurre","champignon"],"target_textures":["feuilletage croustillant","chair_moelleuse","contraste_léger"],"signature_ingredients":["Pavé de saumon cru, sans peau","Pâte feuilletée crue","Aneth frais"],"identity_guardrails":["Tout ce qui entre dans la tourte doit être froid et sec : un riz tiède ou des épinards mal pressés détrempent le fond","Les œufs durs se rangent en file au centre — c''est la tranche qui fait reconnaître un koulibiac","Une cheminée dans le couvercle, sinon la vapeur fait éclater la pâte sur le côté","Un quart d''heure de repos sur grille avant la découpe, sans quoi la tranche s''effondre"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
