  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-031', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('5b145493afeb53e3d9ab465b979c0db4'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"smoky_sweet","scores":{"sweet":4,"salty":5,"acidic":1,"bitter":2,"umami":5,"heat":0,"pungency":2,"richness":4,"freshness":0,"intensity":5},"dominant_flavors":["caramel","nuoc-mâm","porc","gingembre"],"aroma_families":["caramel","soja_fermenté","porc","gingembre"],"target_textures":["viande fondante","sauce laquée","jus court et nappant"],"signature_ingredients":["Échine de porc crue","Sucre semoule","Sauce poisson"],"identity_guardrails":["Caramel à sec poussé jusqu''à l''ambre foncé : blond, il ne donne que du sucre, et c''est son amertume qui équilibre le nuoc-mâm","On garde le gras de l''échine — sans lui la viande est cordée au bout de quarante-cinq minutes","La sauce poisson est indispensable : sans elle, c''est un porc au sucre","La réduction se surveille à l''œil sur la fin : une minute sépare la sauce laquée du fond brûlé"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
