$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Poulet teriyaki', 'poulet teriyaki', 'Japon', 'Japon',
     'meal', 'plat sauté', 'named_traditional_dish', 'spicy_umami',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Poulet teriyaki', 'Blanc de poulet sauté puis glacé dans une sauce soja sucrée au saké et au gingembre', ds.id, 'VAR-032',
    'Myko', 'editorial', 4, 15, 15, 'facile',
    NULL, NULL,
    'B', 'candidate', 'b0e08cf613b67f768e4e2620a24b6c6f',
    '{"sweet":4,"salty":5,"acidic":1,"bitter":1,"umami":5,"heat":0,"pungency":2,"richness":2,"freshness":1,"intensity":4}'::jsonb, ARRAY['sauce soja','sucre caramélisé','gingembre','saké']::text[],
    ARRAY['soja_fermenté','caramel','gingembre','ail']::text[], ARRAY['sauce laquée','chair_moelleuse','nappant']::text[],
    ARRAY['Sauce soja japonaise','Saké de cuisine','Sucre semoule']::text[], ARRAY['Le laquage se construit en retournant souvent dans une sauce qui réduit — versée à la fin, elle ne fait que napper','Le sucre doit être dissous avant la poêle, sinon il brûle par plaques','On arrête dès que la sauce nappe : trente secondes de plus et le sucre vire à l''amer','Le poulet est saisi puis fini dans la sauce, jamais cuit à cœur d''abord']::text[],
    ARRAY['marinade minute','saisie','réduction','laquage']::text[], ARRAY['Au mirin : quatre cuillerées à soupe avec le saké et la sauce soja, forme bloquée au catalogue et donc non écrite ici (marmiton, chefsimon)','Aux hauts de cuisse désossés avec la peau, qui tiennent mieux la réduction (chefsimon)','Finition à l''huile de sésame grillé et aux graines de sésame blanc, avec oignons rouges et échalotes émincés (chefsimon, marmiton)','Au miel d''oranger, 30 g pour deux, et vinaigre balsamique (chefsimon)','Aux ailes de poulet, sauce au ketchup, jus de citron, cassonade et poudre d''ail, 45 minutes au four (marmiton)']::text[], ARRAY['soja','gluten']::text[],
    'Se garde 3 jours au réfrigérateur et se réchauffe deux minutes à la poêle avec une cuillerée d''eau, la sauce s''étant figée. Se mange aussi froid, tranché, sur un riz vinaigré. Se congèle 2 mois, la sauce sucrée-salée protégeant la chair, mais le blanc de poulet en ressort un peu sec — le haut de cuisse supporte mieux. La sauce seule se prépare en avance et se garde 2 semaines au réfrigérateur en bocal : c''est ce qui ramène le plat à dix minutes.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
