  CROSS JOIN unnest(ARRAY['Au mirin : quatre cuillerées à soupe avec le saké et la sauce soja, forme bloquée au catalogue et donc non écrite ici (marmiton, chefsimon)','Aux hauts de cuisse désossés avec la peau, qui tiennent mieux la réduction (chefsimon)','Finition à l''huile de sésame grillé et aux graines de sésame blanc, avec oignons rouges et échalotes émincés (chefsimon, marmiton)','Au miel d''oranger, 30 g pour deux, et vinaigre balsamique (chefsimon)','Aux ailes de poulet, sauce au ketchup, jus de citron, cassonade et poudre d''ail, 45 minutes au four (marmiton)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
