  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-032', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b0e08cf613b67f768e4e2620a24b6c6f'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"spicy_umami","scores":{"sweet":4,"salty":5,"acidic":1,"bitter":1,"umami":5,"heat":0,"pungency":2,"richness":2,"freshness":1,"intensity":4},"dominant_flavors":["sauce soja","sucre caramélisé","gingembre","saké"],"aroma_families":["soja_fermenté","caramel","gingembre","ail"],"target_textures":["sauce laquée","chair_moelleuse","nappant"],"signature_ingredients":["Sauce soja japonaise","Saké de cuisine","Sucre semoule"],"identity_guardrails":["Le laquage se construit en retournant souvent dans une sauce qui réduit — versée à la fin, elle ne fait que napper","Le sucre doit être dissous avant la poêle, sinon il brûle par plaques","On arrête dès que la sauce nappe : trente secondes de plus et le sucre vire à l''amer","Le poulet est saisi puis fini dans la sauce, jamais cuit à cœur d''abord"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
