  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-033","variants":["Avec mirin : trois à quatre cuillerées à soupe dans la tare, forme bloquée au catalogue et donc non écrite ici (marmiton, 750g)","Aux blancs de poulet en lanières, laqués à la sauce teriyaki et au miel, avec ail et gingembre moulu (marmiton)","Finition aux graines de sésame et au shichimi togarashi, mélange d''épices absent du catalogue (chefsimon, 750g)","Servis sur un bol de riz chaud, la tare restante versée sur le riz (chefsimon)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-033', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('9da40335a60542fc24a7ecbd7e3e5052'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"spicy_umami","scores":{"sweet":4,"salty":5,"acidic":0,"bitter":1,"umami":5,"heat":0,"pungency":1,"richness":2,"freshness":1,"intensity":4},"dominant_flavors":["sauce soja réduite","poulet grillé","poireau","sucre caramélisé"],"aroma_families":["soja_fermenté","caramel","végétal grillé"],"target_textures":["sauce laquée","chair_moelleuse","arêtes grillées"],"signature_ingredients":["Haut de cuisse de poulet cru, désossé","Sauce soja japonaise","Poireau cru"],"identity_guardrails":["La tare se réduit avant d''être appliquée : crue, elle coule et ne laque pas","On ne badigeonne qu''en fin de cuisson, en trois ou quatre couches — le sucre brûle en une minute sur un gril chaud","Le poireau alterne avec la viande sur la brochette et n''est pas un accompagnement","Le haut de cuisse plutôt que le blanc : c''est la seule coupe qui supporte la flamme sans sécher"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Bo bun', 'bo bun', 'Vietnam', 'Vietnam',
     'meal', 'salade composée', 'named_traditional_dish', 'fresh_acidic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Bo bun', 'Nouilles de riz froides garnies de bœuf sauté, de carotte et de concombre', ds.id, 'VAR-034',
    'Myko', 'editorial', 4, 30, 10, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '71a27726e347cabcac5580c643c3aa6f',
    '{"sweet":3,"salty":4,"acidic":4,"bitter":0,"umami":4,"heat":1,"pungency":3,"richness":2,"freshness":5,"intensity":4}'::jsonb, ARRAY['nuoc-mâm','citron vert','menthe','bœuf saisi']::text[],
    ARRAY['marin','herbacé','agrume','cacahuète']::text[], ARRAY['nouilles souples','croquant','contraste_léger']::text[],
    ARRAY['Bœuf à griller cru, en fines lamelles','Nouille de riz plate sèche','Sauce poisson']::text[], ARRAY['La sauce se verse à table par chacun : versée en cuisine, elle détrempe la salade en cinq minutes','Les nouilles se rincent longuement à l''eau froide, sinon elles se soudent en bloc au fond du bol','Le bœuf se saisit en deux fournées et arrive brûlant sur des crudités froides — c''est le contraste du plat','Menthe et coriandre entrent crues et déchirées à la main, en quantité franche : ce sont elles qui font le bo bun']::text[],
    ARRAY['marinade minute','cuisson des nouilles','rinçage','saisie à feu vif','assemblage en bol']::text[], ARRAY['Avec nems : deux à huit nems frits coupés en tronçons posés sur le bol, forme absente du catalogue (marmiton, chefsimon, 750g)','À la citronnelle : deux tiges hachées dans la marinade du bœuf, forme bloquée au catalogue (chefsimon, 750g)','Au vinaigre de riz à la place du vinaigre blanc, forme bloquée au catalogue (chefsimon, 750g)','À la sauce d''huître : trois cuillerées à soupe et du curry doux dans la marinade du bœuf (marmiton)','Aux noix de macadamia torréfiées et pilées en plus des cacahuètes (chefsimon)','Aux crevettes à la place du bœuf, sautées deux minutes (marmiton)']::text[], ARRAY['poisson','arachide']::text[],
    'Ne se monte qu''au moment de servir. Les éléments se préparent en revanche à l''avance et séparément : la sauce se garde 2 semaines au réfrigérateur en bocal, les nouilles cuites et rincées 2 jours dans une boîte fermée avec un filet d''huile, les crudités taillées 2 jours, le bœuf mariné cru 24 heures. Rien ne se congèle utilement, sauf le bœuf dans sa marinade, 2 mois. Monté, le bol ne se garde pas : les crudités rendent leur eau en une heure.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
