  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Préparer la sauce en dissolvant le sucre dans le jus de citron vert et le vinaigre, puis en ajoutant la sauce poisson, la moitié de l''ail haché et quatre cuillerées à soupe d''eau. Goûter : elle doit être à la fois franchement salée, nettement acide et perceptiblement sucrée, et paraître trop forte seule — elle sera diluée par les crudités et les vermicelles au fond du bol.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Cuire les nouilles de riz selon leur épaisseur, cinq minutes environ, les égoutter et les rincer longuement à l''eau froide en les démêlant à la main. Le rinçage n''est pas un refroidissement de confort : il retire l''amidon qui, sans cela, soude les nouilles en un bloc compact au fond du bol.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Faire mariner le bœuf taillé en lamelles fines vingt minutes avec le reste de l''ail, l''oignon émincé, du poivre et une cuillerée de sauce poisson. Une marinade courte suffit sur une viande taillée mince : au-delà d''une heure, le sel commence à la raffermir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Râper les carottes en longs filaments, tailler le concombre en bâtonnets, ciseler la salade et laver les pousses de soja. Tout doit être prêt et froid avant que la viande ne touche la poêle : le bo bun se monte en deux minutes, et la viande chaude sur des crudités froides est précisément le contraste recherché.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Saisir le bœuf en deux fois dans une poêle brûlante avec l''huile, deux minutes à peine par fournée, en le laissant colorer sans le remuer sans arrêt. Tout ensemble, il rend son eau et bout dans son jus : il devient gris et coriace, et c''est la seule chose qui puisse rater dans ce plat.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Monter les bols dans l''ordre : salade ciselée au fond, vermicelles par-dessus, puis carotte, concombre et pousses de soja disposés en secteurs, le bœuf brûlant au centre, et pour finir les herbes déchirées à la main et les cacahuètes concassées. Chacun verse la sauce au moment de manger et mélange lui-même — versée en cuisine, elle détrempe la salade en cinq minutes.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-034', 'recipe_family', 'Bo bun',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-034', 'missing_required_count', v_missing), 'open');
  END IF;

