    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-034', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('71a27726e347cabcac5580c643c3aa6f'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"fresh_acidic","scores":{"sweet":3,"salty":4,"acidic":4,"bitter":0,"umami":4,"heat":1,"pungency":3,"richness":2,"freshness":5,"intensity":4},"dominant_flavors":["nuoc-mâm","citron vert","menthe","bœuf saisi"],"aroma_families":["marin","herbacé","agrume","cacahuète"],"target_textures":["nouilles souples","croquant","contraste_léger"],"signature_ingredients":["Bœuf à griller cru, en fines lamelles","Nouille de riz plate sèche","Sauce poisson"],"identity_guardrails":["La sauce se verse à table par chacun : versée en cuisine, elle détrempe la salade en cinq minutes","Les nouilles se rincent longuement à l''eau froide, sinon elles se soudent en bloc au fond du bol","Le bœuf se saisit en deux fournées et arrive brûlant sur des crudités froides — c''est le contraste du plat","Menthe et coriandre entrent crues et déchirées à la main, en quantité franche : ce sont elles qui font le bo bun"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
