  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-036', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b603e2d70167bcf9a4c62a02f20a6af0'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_delicate","scores":{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":3,"heat":0,"pungency":0,"richness":4,"freshness":2,"intensity":2},"dominant_flavors":["saumon","crème","aneth","gruyère"],"aroma_families":["marin","lactée","herbacé","beurre"],"target_textures":["feuilletage croustillant","intérieur_fondant_ou_crémeux","chair_moelleuse"],"signature_ingredients":["Pavé de saumon cru, sans peau","Crème fraîche liquide entière","Aneth frais"],"identity_guardrails":["Le saumon se taille en cubes et non en lamelles : les cubes restent nacrés quand l''appareil est pris","Fond feuilleté cuit à blanc, sans quoi il se compacte en semelle sous l''appareil","L''aneth entre dans l''appareil et non en surface, où il brûlerait","On sort la quiche quand le saumon est juste ferme — c''est lui, et non la couleur du dessus, qui donne le point"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
