  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Couper les courgettes en rondelles de cinq millimètres sans les peler, les saler et les laisser dégorger vingt minutes dans une passoire, puis les éponger. La courgette est faite d''eau à plus de quatre-vingt-dix pour cent : ce quart d''heure lui en retire une partie que le four aurait sinon relâchée directement dans l''appareil.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire sauter les rondelles à feu vif dans l''huile d''olive avec l''ail haché, huit à dix minutes, jusqu''à ce qu''elles soient colorées par endroits et qu''il ne reste plus de liquide dans la poêle. À feu doux elles compotent et rendent encore de l''eau ; à feu vif elles marquent et se referment.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Foncer un moule de la pâte brisée, piquer le fond et le cuire à blanc quinze minutes à 180 °C, lesté de légumes secs. Sans cette précuisson, une garniture de 650 g de légumes détrempe le fond quoi qu''on ait fait pour l''assécher avant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Battre les œufs avec la crème à la fourchette, saler et poivrer généreusement. L''appareil doit être franchement assaisonné : la courgette est douce et neutre, et elle absorbera une partie du sel sans rien rendre en échange.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ranger les courgettes refroidies sur le fond précuit et verser l''appareil, en le laissant s''infiltrer entre les rondelles avant d''en ajouter. Versé d''un coup, il flotte au-dessus et déborde du moule alors que des poches d''air subsistent en dessous.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Enfourner à 180 °C pour trente-cinq minutes, jusqu''à ce que le dessus soit doré et le centre juste pris. Laisser reposer dix minutes avant de découper : sans fromage pour la lier, cette quiche tient uniquement par la coagulation de l''œuf, qui achève de se faire hors du four.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-037', 'recipe_family', 'Quiche aux courgettes',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-037', 'missing_required_count', v_missing), 'open');
  END IF;

