  CROSS JOIN unnest(ARRAY['Au chèvre frais : 150 g répartis sur les courgettes (marmiton)','Au parmesan, 60 à 100 g râpés dans l''appareil (chefsimon, deux pages)','À la feta émiettée et à la menthe, sur une pâte au sarrasin et un appareil au yaourt entier (chefsimon)','Aux lardons : 100 à 250 g rissolés et égouttés, ajoutés avec les courgettes (marmiton, 750g)','Au pistou : basilic, ail, parmesan et huile d''olive mixés et étalés sur le fond avant les courgettes (chefsimon)','Aux amandes effilées et aux herbes fraîches, menthe et coriandre (chefsimon)']::text[]) AS variant(name);

