  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-037', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('658a5397ff51dc1108c9f204ea972cce'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":3,"salty":3,"acidic":0,"bitter":0,"umami":2,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":2},"dominant_flavors":["courgette","crème","ail","huile d''olive"],"aroma_families":["végétal cuit","lactée","ail","huile_olive"],"target_textures":["pâte sablée","intérieur_fondant_ou_crémeux","rondelles fermes"],"signature_ingredients":["Courgette fraîche","Crème fraîche liquide entière","Œuf cru"],"identity_guardrails":["Les courgettes se dégorgent puis se sautent à feu vif : sans les deux, la quiche rend de l''eau au four","Aucun fromage n''est écrit ici et c''est le dossier qui le dicte — cinq pages, cinq fromages, aucun sur deux sites","Fond cuit à blanc : 650 g de légumes sur une pâte crue donnent une semelle molle","L''appareil se verse en deux fois, le temps qu''il s''infiltre entre les rondelles"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Quiche au thon', 'quiche au thon', 'France', 'France',
     'meal', 'tarte salée', 'domestic_standard', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Quiche au thon', 'Tarte salée au thon et à la tomate dans un appareil œufs-crème, gratinée', ds.id, 'VAR-038',
    'Myko', 'editorial', 6, 20, 35, 'facile',
    NULL, NULL,
    'B', 'candidate', '112ca4e35b0fa97bec865ae9272f8335',
    '{"sweet":2,"salty":3,"acidic":3,"bitter":0,"umami":4,"heat":0,"pungency":3,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['thon','tomate','moutarde','gruyère']::text[],
    ARRAY['marin','tomate','moutarde','lactée']::text[], ARRAY['pâte sablée','intérieur_fondant_ou_crémeux','tomate confite']::text[],
    ARRAY['Thon au naturel en conserve, égoutté','Tomate fraîche mûre','Moutarde de Dijon']::text[], ARRAY['Les tomates s''épépinent et s''égouttent vingt minutes : sans cela l''appareil ne prend pas au centre','La moutarde s''étale sur le fond cru, avant la cuisson à blanc — c''est un goût et une barrière à l''humidité','Les tomates se posent en surface et ne s''enfoncent pas dans l''appareil, où elles rendraient leur eau','Thon émietté en lamelles, jamais écrasé en pâte']::text[],
    ARRAY['dégorgement','cuisson à blanc','appareil','cuisson au four','repos']::text[], ARRAY['Au thon frais : 450 g pour quatre, avec deux échalotes et du paprika (750g)','À la mozzarella : 200 g en tranches sur les tomates, avec basilic et persil (marmiton)','À la ratatouille : 300 g égouttés à la place des tomates fraîches (marmiton)','Aux trois poivrons et à la tomme de brebis, avec des pignons (chefsimon)','Aux petits pois : 100 g surgelés avec de la coriandre et du parmesan (chefsimon)','Aux olives noires et à la cive, quatre gousses d''ail dans l''appareil (750g)']::text[], ARRAY['gluten','lait','œuf','poisson','moutarde']::text[],
    'Se garde 3 jours au réfrigérateur et se réchauffe 12 minutes à 180 °C ; elle est aussi bonne froide, ce qui en fait un pique-nique. Se congèle 2 mois cuite, en parts filmées, mais la tomate y perd de sa tenue et rend un peu d''eau à la décongélation : réchauffer alors directement au four sans passer par le réfrigérateur.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
