  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Couper les tomates en rondelles, les épépiner à la pointe du couteau et les laisser égoutter vingt minutes sur du papier absorbant, salées. C''est l''étape que la moitié des pages passent sous silence et qui décide de tout : une tomate non égouttée rend deux à trois cuillerées d''eau dans l''appareil, qui ne prend alors jamais au centre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Foncer un moule de pâte brisée, piquer le fond, et étaler la moutarde en couche mince sur toute la surface. La moutarde n''est pas seulement un goût : sa couche grasse fait une barrière entre la pâte et le jus de la garniture, et c''est pour cela que quatre pages du dossier commencent ainsi.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Cuire le fond à blanc douze minutes à 180 °C, lesté. La moutarde sèche pendant cette précuisson et adhère à la pâte au lieu de se diluer dans l''appareil.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Égoutter et émietter le thon à la fourchette, sans le réduire en pâte : on veut des lamelles qui se reconnaissent sous la dent, pas une farce homogène. Le répartir sur le fond précuit avec la moitié du gruyère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Battre les œufs avec la crème et le lait, saler avec retenue — le thon en conserve et le fromage en apportent déjà — poivrer, et verser sur le thon. Ranger les rondelles de tomate épongées sur le dessus, à plat et sans les enfoncer, et parsemer du reste de gruyère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Enfourner à 180 °C pour trente-cinq minutes, jusqu''à ce que les tomates soient ridées sur les bords et l''appareil pris. Les tomates posées en surface et non noyées cuisent et se concentrent au lieu de rendre leur eau dans le flan : c''est la seule façon d''en mettre 500 g sans détremper la quiche. Laisser reposer dix minutes avant de découper.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-038', 'recipe_family', 'Quiche au thon',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-038', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Au thon frais : 450 g pour quatre, avec deux échalotes et du paprika (750g)','À la mozzarella : 200 g en tranches sur les tomates, avec basilic et persil (marmiton)','À la ratatouille : 300 g égouttés à la place des tomates fraîches (marmiton)','Aux trois poivrons et à la tomme de brebis, avec des pignons (chefsimon)','Aux petits pois : 100 g surgelés avec de la coriandre et du parmesan (chefsimon)','Aux olives noires et à la cive, quatre gousses d''ail dans l''appareil (750g)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-038","variants":["Au thon frais : 450 g pour quatre, avec deux échalotes et du paprika (750g)","À la mozzarella : 200 g en tranches sur les tomates, avec basilic et persil (marmiton)","À la ratatouille : 300 g égouttés à la place des tomates fraîches (marmiton)","Aux trois poivrons et à la tomme de brebis, avec des pignons (chefsimon)","Aux petits pois : 100 g surgelés avec de la coriandre et du parmesan (chefsimon)","Aux olives noires et à la cive, quatre gousses d''ail dans l''appareil (750g)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-038', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('112ca4e35b0fa97bec865ae9272f8335'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":2,"salty":3,"acidic":3,"bitter":0,"umami":4,"heat":0,"pungency":3,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["thon","tomate","moutarde","gruyère"],"aroma_families":["marin","tomate","moutarde","lactée"],"target_textures":["pâte sablée","intérieur_fondant_ou_crémeux","tomate confite"],"signature_ingredients":["Thon au naturel en conserve, égoutté","Tomate fraîche mûre","Moutarde de Dijon"],"identity_guardrails":["Les tomates s''épépinent et s''égouttent vingt minutes : sans cela l''appareil ne prend pas au centre","La moutarde s''étale sur le fond cru, avant la cuisson à blanc — c''est un goût et une barrière à l''humidité","Les tomates se posent en surface et ne s''enfoncent pas dans l''appareil, où elles rendraient leur eau","Thon émietté en lamelles, jamais écrasé en pâte"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Omelette au fromage', 'omelette au fromage', 'France', 'France',
     'meal', 'omelette', 'domestic_standard', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
