  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Au comté râpé, 100 g pour six, avec un jus de citron et des blancs montés en neige — omelette soufflée passée au four (marmiton)','À la bûche de chèvre, 100 g pour deux, avec une courgette poêlée et des herbes de Provence (chefsimon)','Mozzarella et gruyère à parts égales, 50 g de chaque pour deux, avec de la crème liquide, de l''ail et du paprika (750g)','Au fromage blanc, 400 g pour quatre, avec des pignons de pin et de la ciboulette (750g)','Au fromage frais ail et fines herbes, 50 g pour deux, avec du bacon (marmiton)','Au parmesan râpé et au jambon blanc, deux tranches (marmiton)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-039","variants":["Au comté râpé, 100 g pour six, avec un jus de citron et des blancs montés en neige — omelette soufflée passée au four (marmiton)","À la bûche de chèvre, 100 g pour deux, avec une courgette poêlée et des herbes de Provence (chefsimon)","Mozzarella et gruyère à parts égales, 50 g de chaque pour deux, avec de la crème liquide, de l''ail et du paprika (750g)","Au fromage blanc, 400 g pour quatre, avec des pignons de pin et de la ciboulette (750g)","Au fromage frais ail et fines herbes, 50 g pour deux, avec du bacon (marmiton)","Au parmesan râpé et au jambon blanc, deux tranches (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-039', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('4e87ed353c10fd8c334b285a9a93a747'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":0,"intensity":2},"dominant_flavors":["œuf","gruyère fondu","beurre"],"aroma_families":["beurre","lacté","fromage affiné"],"target_textures":["baveux au cœur","fromage filant","moelleux"],"signature_ingredients":["Œuf cru","Gruyère râpé","Beurre doux"],"identity_guardrails":["Les œufs se battent dix secondes, pas davantage : une mousse donne une omelette sèche","Le fromage entre quand la surface est encore brillante — plus tôt il se disperse, plus tard il ne fond pas","Beurre blond et non noisette : noirci, il couvre le goût du fromage","L''omelette se sert baveuse au cœur et finit de cuire dans le plat"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
