  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Trancher les tomates en rondelles de cinq millimètres, les ranger à plat sur une grille ou du papier absorbant, les saler légèrement et les laisser rendre leur eau une demi-heure. Sans appareil aux œufs pour absorber ce jus, cette demi-heure est la seule protection de la pâte, et c''est elle qui décide entre une tarte croustillante et une tarte molle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Émincer l''oignon en lamelles fines et le faire fondre dix minutes dans la moitié de l''huile d''olive, sans coloration. Cru sous les tomates, il reste croquant et piquant sous une tarte par ailleurs douce, et c''est un décalage qu''on remarque à chaque bouchée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Foncer un moule de la pâte brisée, piquer le fond à la fourchette et le cuire à blanc quinze minutes à 180 °C, lesté. Une tarte à la tomate sans appareil n''a rien pour tenir sa pâte au sec : la cuisson à blanc n''est pas ici une commodité, c''est la structure du plat.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Étaler la moutarde en couche mince sur le fond précuit et encore chaud, puis répartir l''oignon fondu par-dessus. La moutarde sur une pâte chaude sèche instantanément et forme un film ; posée sur une pâte froide, elle reste humide sous les tomates.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ranger les rondelles de tomate épongées en rosace, en les faisant se chevaucher légèrement, poivrer et parsemer des herbes de Provence puis du gruyère râpé. Un chevauchement léger et non un empilement : deux épaisseurs de tomate ne cuisent pas, elles s''affaissent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Arroser du reste d''huile d''olive et enfourner à 180 °C pour quarante minutes, jusqu''à ce que les bords des rondelles soient bruns et légèrement ridés. C''est cette caramélisation des bords qui concentre le goût de la tomate ; une tarte sortie trop tôt est aqueuse et fade quelle que soit la qualité des fruits. Laisser tiédir dix minutes avant de couper.');

