  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Tailler l''oignon, la carotte, la courgette et l''aubergine en dés de trois à quatre millimètres, aussi réguliers que possible. C''est la seule opération vraiment longue de la recette et c''est aussi la seule qui compte : à cette taille, les légumes fondent en une masse qui accroche aux pâtes comme le fait une viande hachée. En dés d''un centimètre, on obtient une ratatouille et non une bolognaise, et aucune cuisson ne rattrape la découpe.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire revenir l''oignon et la carotte dans l''huile d''olive à feu moyen pendant dix minutes, puis ajouter l''aubergine et la courgette et poursuivre dix minutes en remuant. L''aubergine boit beaucoup d''huile dans les premières minutes puis la relâche : ne pas en rajouter à ce moment-là, sous peine d''une sauce grasse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Ajouter l''ail haché et le concentré de tomate, remuer deux minutes à feu vif jusqu''à ce que le concentré fonce légèrement et sente le grillé. C''est ce court passage sur le feu qui lui retire son goût métallique et apporte à la sauce la profondeur qu''un ragù tire de la viande saisie.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser les tomates concassées, le sucre, saler et poivrer, et laisser mijoter trente-cinq minutes à découvert et à feu doux, en remuant de temps à autre pour décoller le fond. La sauce est prête quand un sillon tracé à la cuillère au fond de la casserole met deux secondes à se refermer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Goûter et rectifier le sel et le sucre. Une sauce de légumes est plus acide qu''un ragù parce que rien n''y apporte de gras animal pour l''arrondir : c''est le rôle du morceau de sucre, et il faut parfois en ajouter un second selon les tomates.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Hors du feu, incorporer le basilic déchiré à la main. Ajouté en cours de cuisson, il noircit et perd tout son parfum en cinq minutes ; jeté à la fin dans une sauce encore brûlante, il infuse juste assez.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
