  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Sortir les crevettes du congélateur et les laisser dégeler une demi-heure dans une passoire posée sur un saladier, ou dix minutes sous un filet d''eau froide. Les éponger ensuite longuement dans un linge : c''est le geste qui décide de tout, une crevette encore humide bout dans sa propre eau au lieu de saisir, et rend une chair grise et molle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Éplucher les gousses, retirer le germe vert du centre s''il est formé, puis les hacher au couteau plutôt qu''au presse-ail. Le presse-ail écrase les cellules et libère une amertume qui ressort à la friture ; le couteau laisse des éclats qui blondissent sans brûler. Ciseler le persil et le réserver à part.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffer l''huile dans une grande poêle à feu moyen, y jeter l''ail et le remuer trente à quarante secondes, le temps qu''il embaume et prenne une couleur de paille. Ne pas le laisser aller au brun : passé cette teinte il devient âcre et l''amertume traverse le plat entier. Si cela arrive, jeter l''huile et recommencer coûte moins cher que de servir le plat.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Monter le feu au maximum, verser les crevettes en une seule couche et ne plus y toucher pendant une minute. Les retourner et compter une minute encore : elles sont cuites dès qu''elles ont pris leur couleur orangée et se sont refermées en virgule. Une crevette qui se referme en anneau serré a déjà trop cuit.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Retirer du feu, saler, poivrer, poudrer du piment d''Espelette, puis verser le jus de citron dans la poêle brûlante : il décolle en sifflant les sucs collés au fond et lie l''huile en un jus court. Ajouter le persil et mélanger une dernière fois. Servir immédiatement, la poêle continuant de cuire ce qu''on y laisse.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'DEN-001', 'recipe_family', 'Crevettes sautées à l''ail',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

