  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Ciseler finement les échalotes, hacher l''ail, concasser les tomates. Faire fondre les échalotes dans l''huile à feu moyen pendant cinq minutes jusqu''à ce qu''elles deviennent translucides, puis ajouter l''ail et le laisser une demi-minute seulement.');

