  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Rincer le mélange encore gelé sous l''eau froide, l''égoutter puis le presser doucement entre deux feuilles de papier absorbant. Chaque gramme d''eau qu''on retire ici est un gramme qu''on n''aura pas à faire évaporer dans la sauce, où il diluerait la crème.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Ciseler l''échalote très finement et la faire fondre dans la moitié du beurre à feu doux, cinq minutes, sans coloration. Délayer la fécule dans deux cuillerées d''eau froide et réserver ce mélange à portée de main : une fécule versée sèche dans un liquide chaud fait des grumeaux qu''aucun fouet ne rattrape.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Verser le vin blanc sur l''échalote et laisser réduire de moitié à feu vif, cinq à six minutes. Cette réduction est le fond de goût de la cassolette : un vin simplement chauffé garderait son acidité alcoolique et la crème ne la couvrirait pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter le concentré de tomate, remuer une minute pour le cuire — cru, il garde un goût de boîte — puis verser la crème et porter à frémissement. Incorporer la fécule délayée en fouettant et laisser épaissir deux minutes, jusqu''à ce que la sauce nappe une cuillère sans couler.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Hors du feu, incorporer les fruits de mer égouttés et le reste du beurre en parcelles, saler et poivrer. Répartir dans quatre cassolettes ou ramequins et enfourner cinq à six minutes à 200 °C, le temps que le dessus prenne des taches dorées. Semer le persil ciselé à la sortie.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'DEN-004', 'recipe_family', 'Cassolette de fruits de mer',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'DEN-004', 'missing_required_count', v_missing), 'open');
  END IF;

