  CROSS JOIN unnest(ARRAY['Un pavé de colin ou de cabillaud par personne, posé dans la cassolette sous les fruits de mer (marmiton)','Champignons de Paris émincés fondus avec l''échalote, et deux cuillerées de pesto dans la sauce (chefsimon)','Une pointe de curry ou un demi-cuillère de gingembre en poudre dans la crème (marmiton)','Chapelure fine semée avant le passage au four, pour une croûte franchement croustillante (marmiton)']::text[]) AS variant(name);

