  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:DEN-004', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b2c02610db9ab350c78bbe6ef3b61ff2'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["fruits de mer","vin blanc réduit","crème","échalote"],"aroma_families":["fruits_de_mer","vin_blanc_réduit","crème","échalote"],"target_textures":["sauce nappante","chair nacrée et moelleuse","dessus doré"],"signature_ingredients":["Fruits de mer cuits surgelés","Crème fraîche liquide entière","Vin blanc sec"],"identity_guardrails":["Le vin réduit de moitié avant la crème : sans cette réduction la sauce reste acide et plate","Les fruits de mer entrent hors du feu, ils sont déjà cuits et ne font que se réchauffer au four","La sauce est liée à la fécule, pas par la seule réduction de la crème — c''est ce qui la tient en cassolette","Pas de fromage râpé : ce qui dore ici est la crème, pas une croûte gratinée"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Gratin de fruits de mer', 'gratin de fruits de mer', 'France / cuisine domestique', 'France / cuisine domestique',
     'meal', 'gratin', 'domestic_standard', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Gratin de fruits de mer', 'Fruits de mer surgelés nappés d''une béchamel crémée, gruyère et chapelure, dorés une demi-heure au four', ds.id, 'DEN-005',
    'Myko', 'editorial', 4, 20, 30, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '3148c4efdd62694e121897f8c025fa9b',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":0,"intensity":3}'::jsonb, ARRAY['fruits de mer','béchamel','gruyère fondu','beurre']::text[],
    ARRAY['fruits_de_mer','béchamel','gruyère','beurre']::text[], ARRAY['croûte gratinée','sauce nappante','chair nacrée et moelleuse']::text[],
    ARRAY['Fruits de mer cuits surgelés','Gruyère râpé','Lait entier']::text[], ARRAY['Les fruits de mer sont égouttés longuement : leur eau sous une croûte fait un gratin noyé','Le roux cuit deux minutes avant le lait, sinon la béchamel garde un goût de farine','La béchamel reste souple : elle recevra encore l''eau rendue par les fruits de mer au four','Trente minutes au four suffisent — au-delà, les fruits de mer déjà cuits se dessèchent sous la croûte']::text[],
    ARRAY['égouttage','roux','béchamel','assemblage','gratinage']::text[], ARRAY['Quatre quenelles de brochet couchées dans le plat sous la béchamel (marmiton, deux pages)','Chanterelles poêlées et un trait de vin blanc dans la sauce (marmiton)','Pommes de terre en rondelles précuites et bouquets de brocoli en couche du dessous (chefsimon)','Bisque de homard à la place d''une partie du lait, pour une sauce nettement plus iodée (chefsimon)']::text[], ARRAY['crustacés','mollusques','lait','gluten']::text[],
    'Se garde 2 jours au réfrigérateur entre 0 et 4 °C, filmé une fois refroidi, et se réchauffe vingt minutes à 180 °C plutôt qu''au micro-ondes, qui détrempe la croûte. Ne se congèle pas, ni pour les fruits de mer déjà congelés une fois, ni pour la béchamel, qui tranche à la décongélation.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
