  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Mettre l''eau des pâtes à chauffer en premier, généreusement salée. Pendant qu''elle monte, rincer les fruits de mer encore gelés à l''eau froide et les laisser s''égoutter dans une passoire : ils continueront de rendre de l''eau, et c''est très bien qu''ils la rendent là plutôt que dans la sauce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Ciseler l''échalote et la faire fondre dans l''huile à feu doux pendant cinq minutes. Verser le vin blanc et laisser réduire presque à sec, jusqu''à ce qu''il ne reste qu''un fond sirupeux au fond de la poêle : c''est là que se concentre tout le goût de la sauce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Jeter les pâtes dans l''eau bouillante et les cuire une minute de moins que le temps du paquet. Prélever une louche d''eau de cuisson avant d''égoutter — cette eau chargée d''amidon est ce qui liera la sauce aux pâtes, et une fois l''évier ouvert on ne la rattrape plus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser la crème sur la réduction d''échalote, porter à frémissement et laisser deux minutes. Ajouter les fruits de mer bien égouttés et compter trois minutes à feu moyen, le temps qu''ils soient chauds à cœur : ils sont vendus cuits, un séjour plus long ne ferait que les raidir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser les pâtes égouttées directement dans la poêle avec deux ou trois cuillerées d''eau de cuisson et faire sauter une minute à feu vif, en remuant sans arrêt. La sauce doit enrober chaque pâte et non stagner au fond. Poivrer, ajouter le persil ciselé, goûter et rectifier le sel avant de servir.');

  INSERT INTO quality.review_tasks
