  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:DEN-006', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('395f68b024edb6133226b3a93d5c9e8c'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3},"dominant_flavors":["fruits de mer","crème","vin blanc réduit","échalote"],"aroma_families":["fruits_de_mer","crème","vin_blanc_réduit","persil"],"target_textures":["pâtes_fermes","sauce nappante","chair nacrée et moelleuse"],"signature_ingredients":["Pâtes sèches courtes","Fruits de mer cuits surgelés","Crème fraîche liquide entière"],"identity_guardrails":["Le vin réduit presque à sec avant la crème : c''est la concentration qui fait la sauce, pas la quantité","L''eau de cuisson des pâtes lie la sauce — l''égouttage sans prélèvement est une erreur irréversible","Les fruits de mer chauffent trois minutes, jamais davantage : ils arrivent déjà cuits","Pas d''ail : aucune des quatre sources retenues n''en porte, et l''ajouter changerait le plat"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
