  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Décongeler les crevettes dans une passoire, sous un filet d''eau froide pendant dix minutes, puis les sécher soigneusement dans un linge. Une crevette humide ne saisit pas : elle relâche son eau dans la poêle et bout, et cette différence-là se voit à l''assiette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Chauffer la moitié de l''huile à feu vif, y jeter les crevettes en une seule couche et les saisir une minute par face, juste le temps qu''elles rosissent. Les débarrasser aussitôt dans une assiette : elles finiront leur cuisson dans la sauce, et leur faire faire tout le trajet dans la poêle les durcirait.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Baisser le feu, verser le reste de l''huile et l''ail haché dans la même poêle, remuer trente secondes, puis ajouter la tomate concassée. Saler et laisser mijoter quinze minutes à découvert, jusqu''à ce que la sauce ait perdu son eau et se soit resserrée autour de l''huile.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Cuire les spaghettis dans un grand volume d''eau salée, une minute de moins que le temps indiqué, et garder une louche d''eau de cuisson au moment d''égoutter. C''est l''amidon de cette eau qui fera tenir la sauce sur les pâtes plutôt que de la laisser glisser au fond de l''assiette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
