  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'required',
     'assaisonnement', false, 8);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Décongeler les filets une nuit au réfrigérateur sur une grille, puis les éponger des deux côtés. Le lieu noir se délite plus facilement que le cabillaud : une chair sèche en surface tient à la poêle, une chair mouillée s''y défait en morceaux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Saler et poivrer les filets, chauffer l''huile à feu vif dans une poêle large et les poser côté peau ou côté le plus bombé. Ne plus y toucher pendant trois minutes : le poisson se décolle de lui-même quand la croûte est prise, et vouloir le soulever plus tôt est le meilleur moyen de le déchirer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Retourner les filets, compter deux minutes de plus, puis les débarrasser sur une assiette chaude. Ils ne sont pas tout à fait cuits à cœur, et c''est voulu : ils finiront dans la sauce, où ils resteront moelleux au lieu de se dessécher dans la poêle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Baisser le feu sous la poêle, verser la crème et gratter le fond à la cuillère de bois pour reprendre les sucs collés. Laisser frémir deux minutes, puis délayer la moutarde hors du feu : cuite, une moutarde perd son piquant et ne laisse que son amertume, et c''est son piquant qui fait le plat.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Remettre les filets dans la sauce, arroser à la cuillère pendant deux minutes à feu doux, puis couper le feu. Ajouter le persil et la ciboulette ciselés, goûter, rectifier le sel et servir aussitôt dans la poêle ou sur assiette très chaude.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'DEN-009', 'recipe_family', 'Lieu noir à la crème',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
