  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Tailler tous les légumes AVANT d''allumer le feu, et de la même épaisseur : carottes en fines rondelles ou en bâtonnets, courgette en demi-lunes, poivron en lanières. Un wok se conduit en cinq minutes montre en main, et il n''y a aucun moment pour couper quoi que ce soit une fois la poêle chaude.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Couper le poulet en lanières en travers des fibres, le saler et le poivrer, et le mélanger au paprika. Hacher l''ail, râper le gingembre, ciseler l''échalote et réserver ces trois-là ensemble dans un bol : ils entreront au même moment.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffer l''huile d''arachide dans un wok jusqu''à ce qu''elle ondule, saisir le poulet en deux fournées à feu maximal, trois minutes chacune, en secouant le wok plutôt qu''en remuant à la cuillère. Débarrasser dès qu''il est doré.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Jeter les carottes seules deux minutes, puis le poivron une minute, puis la courgette une minute : l''ordre suit la fermeté, et c''est lui qui décide de tout dans un wok. Ajouter l''échalote, l''ail et le gingembre et remuer trente secondes de plus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Remettre le poulet, verser la sauce soja et laisser bouillonner une minute pour qu''elle enrobe. Couper le feu, ajouter l''huile de sésame et la coriandre ciselée, mélanger une dernière fois et servir sans attendre — les légumes perdent leur croquant en deux minutes dans un plat couvert.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'DEN-015', 'recipe_family', 'Wok de poulet aux légumes',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'DEN-015', 'missing_required_count', v_missing), 'open');
  END IF;

