    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Petits pois et pois mange-tout ajoutés avec la courgette (marmiton)','Jeunes épis de maïs et pak choï, sauce aigre-douce pimentée à part (chefsimon)','Curry en poudre à la place du paprika et du gingembre (marmiton)','Champignons noirs réhydratés et tomates cerise en fin de cuisson (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"DEN-015","variants":["Petits pois et pois mange-tout ajoutés avec la courgette (marmiton)","Jeunes épis de maïs et pak choï, sauce aigre-douce pimentée à part (chefsimon)","Curry en poudre à la place du paprika et du gingembre (marmiton)","Champignons noirs réhydratés et tomates cerise en fin de cuisson (chefsimon)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:DEN-015', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('aa518157940f75a6589ce6fa97b35b68'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":2,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":2,"freshness":3,"intensity":3},"dominant_flavors":["poulet doré","légumes croquants","sauce soja","sésame"],"aroma_families":["poulet","légumes","soja","sésame_toasté"],"target_textures":["tendre","légumes tendres","croquant"],"signature_ingredients":["Blanc de poulet cru, sans peau","Sauce soja","Huile de sésame grillé"],"identity_guardrails":["Tout est taillé avant d''allumer : un wok ne laisse pas le temps de couper","Les légumes entrent par ordre de fermeté, jamais tous ensemble","L''huile de sésame est une finition hors du feu, pas une huile de cuisson","Les légumes restent croquants — un wok mou est un wok raté, et se sert immédiatement"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Poulet aux lentilles', 'poulet aux lentilles', 'France / cuisine domestique', 'France / cuisine domestique',
     'meal', 'plat complet mijoté', 'domestic_standard', 'earthy_herbal',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Poulet aux lentilles', 'Lentilles vertes mijotées avec des morceaux de poulet doré, l''oignon et le thym, finies à la coriandre', ds.id, 'DEN-016',
    'Myko', 'editorial', 4, 15, 40, 'facile',
    NULL, NULL,
    'B', 'candidate', '528e3d31086da72fff7221c7aa822715',
    '{"sweet":1,"salty":2,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":2,"intensity":3}'::jsonb, ARRAY['lentille','poulet doré','oignon fondu','coriandre']::text[],
    ARRAY['lentille','poulet','oignon_compoté','coriandre']::text[], ARRAY['lentilles fondantes mais entières','tendre','jus court et nappant']::text[],
    ARRAY['Blanc de poulet cru, sans peau','Lentille verte sèche, crue','Coriandre fraîche']::text[], ARRAY['Le sel n''entre qu''après vingt-cinq minutes : salées trop tôt, les lentilles restent dures','Les lentilles ne trempent pas — elles se déliteraient','Pas de lardons : ce serait « Lentilles au lard », un autre plat du corpus','Le poulet est doré à part et revient à la fin, sinon il cuit quarante minutes et devient sec']::text[],
    ARRAY['saisie','déglaçage','mijotage','assaisonnement tardif','repos']::text[], ARRAY['250 g de lardons rissolés avec l''oignon et un verre de vin blanc, ce qui rapproche le plat des « Lentilles au lard » du corpus (marmiton)','Curry, cumin, ail et tomates, avec deux pommes de terre en cubes (marmiton)','Gingembre, curcuma et estragon, façon lentilles de Cilaos (marmiton)','Mélange cajun et poivrons piquillos, servi tiède en salade (750g)']::text[], ARRAY[]::text[],
    'Se garde 4 jours au réfrigérateur entre 0 et 4 °C et gagne au repos, les lentilles finissant d''absorber le bouillon. Se congèle 3 mois en portions ; ajouter une cuillerée d''eau au réchauffage, les lentilles ayant encore épaissi.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
