  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:DEN-016', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('528e3d31086da72fff7221c7aa822715'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"earthy_herbal","scores":{"sweet":1,"salty":2,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":2,"intensity":3},"dominant_flavors":["lentille","poulet doré","oignon fondu","coriandre"],"aroma_families":["lentille","poulet","oignon_compoté","coriandre"],"target_textures":["lentilles fondantes mais entières","tendre","jus court et nappant"],"signature_ingredients":["Blanc de poulet cru, sans peau","Lentille verte sèche, crue","Coriandre fraîche"],"identity_guardrails":["Le sel n''entre qu''après vingt-cinq minutes : salées trop tôt, les lentilles restent dures","Les lentilles ne trempent pas — elles se déliteraient","Pas de lardons : ce serait « Lentilles au lard », un autre plat du corpus","Le poulet est doré à part et revient à la fin, sinon il cuit quarante minutes et devient sec"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
