  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Deux bâtons de cannelle mijotés entiers à la place de la poudre, et un verre de riz cuit dans le bouillon (marmiton)','Six feuilles de laurier, un verre de vin blanc et des cuisses de poulet à la place des blancs (marmiton)','Tomates concassées, carottes et lardons (marmiton)','Crème semi-épaisse et curry de Madras à la place de la cannelle, avec des petits pois (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"DEN-017","variants":["Deux bâtons de cannelle mijotés entiers à la place de la poudre, et un verre de riz cuit dans le bouillon (marmiton)","Six feuilles de laurier, un verre de vin blanc et des cuisses de poulet à la place des blancs (marmiton)","Tomates concassées, carottes et lardons (marmiton)","Crème semi-épaisse et curry de Madras à la place de la cannelle, avec des petits pois (chefsimon)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:DEN-017', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('c8ab8adf2b76a7a5df4528fcdb5e86ab'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":2,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":1,"intensity":3},"dominant_flavors":["poulet doré","pois chiche","cannelle","poivron fondu"],"aroma_families":["poulet","légumineuse grillée","cannelle","poivron"],"target_textures":["tendre","haricot fondant à peau intacte","jus court et nappant"],"signature_ingredients":["Blanc de poulet cru, sans peau","Pois chiche cuit, égoutté","Cannelle moulue"],"identity_guardrails":["La cannelle est une pointe aromatique, jamais un accent sucré","Les pois chiches sont rincés jusqu''à ce que l''eau cesse de mousser","Le poulet dore à part et ne revient qu''à la fin : mijoté vingt minutes, un blanc devient sec","Pas de crème ni de curry : ils viennent des deux pages d''un même auteur et restent en variante"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
