  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Épépiner les tomates et les couper en dés, les ajouter à l''oignon avec le paprika et laisser deux à trois minutes à feu vif pour que leur eau parte. Saler légèrement en tenant compte du sel du thon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
