  FROM axis
  CROSS JOIN unnest(ARRAY['Dos de cabillaud à la place du merlu (marmiton, chefsimon, 750g)','Pâte de curry rouge à la place des épices moulues, avec des carottes en rondelles (marmiton)','Graines de moutarde et feuilles de cari jetées dans l''huile avant l''oignon, façon Kerala (chefsimon)','Courgettes en dés et petits pois ajoutés avec la tomate (chefsimon)','Un sachet de fruits de mer surgelés ajouté avec le poisson, et du garam masala (750g)']::text[]) AS variant(name);

