  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:DEN-023', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b31b29725eebd43b7349c89466026fb3'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":2,"acidic":2,"bitter":0,"umami":3,"heat":2,"pungency":3,"richness":3,"freshness":2,"intensity":4},"dominant_flavors":["poisson poché","curry","tomate cuite","lait de coco"],"aroma_families":["poisson","curry","tomate_cuite","coco"],"target_textures":["chair fondante","sauce nappante"],"signature_ingredients":["Filet de merlu surgelé","Curry en poudre","Lait de coco"],"identity_guardrails":["Les épices passent dans l''huile chaude avant tout liquide, sinon le curry reste terreux","Le poisson poche à couvert sans jamais être remué à la cuillère","Le lait de coco ne bout pas — il lie, la tomate porte le plat","Cubes de quatre centimètres : plus petits, ils se délitent dans la sauce"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Pot-au-feu de poule', 'pot au feu de poule', 'France', 'France',
     'meal', 'plat complet mijoté', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Pot-au-feu de poule', 'Poule entière pochée longuement avec carottes, navets, poireau et céleri, sans farce', ds.id, 'SRC-001-D1',
    'Myko', 'editorial', 6, 20, 180, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '6fc35bc9a493accb8dfd5f97f60656cf',
    '{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":0,"heat":3,"pungency":0,"richness":2,"freshness":4,"intensity":1}'::jsonb, ARRAY['bouillon_de_volaille','légumes_racines','farce_au_jambon']::text[],
    ARRAY['volaille_pochée','légume_bouilli','muscade']::text[], ARRAY['chair_fondante','bouillon_clair','farce_moelleuse']::text[],
    ARRAY['Poule crue','Clou de girofle']::text[], ARRAY['Le bouillon reste clair : on écume et on ne laisse jamais bouillir.','La poule est farcie — sans farce, c''est un pot-au-feu de volaille, pas une poule au pot.']::text[],
    ARRAY['pochage','farce','écumage','cuisson longue']::text[], ARRAY[]::text[], ARRAY['gluten','œuf','lait']::text[],
    'Le bouillon se garde 4 jours au froid et se congèle. La poule se conserve 3 jours immergée dans son bouillon, jamais à sec.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-001'), '{"variant_label":"Sans farce, en pot-au-feu de volaille","rationale":"La farce est ce qui distingue la poule au pot de la simple volaille pochée : la retirer donne un autre plat, plus rapide à monter et plus léger, où le bouillon prend toute la place.","operations":[{"op":"remove","form":"Pain de mie"},{"op":"remove","form":"Lait entier"},{"op":"remove","form":"Œuf cru"},{"op":"remove","form":"Jambon blanc cuit"},{"op":"remove","form":"Muscade moulue"},{"op":"set","form":"Ail cru","quantity":10,"role":"aromate"},{"op":"set","form":"Persil plat frais","quantity":10,"role":"finition"}],"steps":[{"op":"remove","n":1},{"op":"remove","n":2},{"op":"replace","n":3,"instruction":"Brider la volaille sans la garnir, pour qu''elle garde sa forme pendant les trois heures de cuisson."},{"op":"replace","n":5,"instruction":"Ajouter l''oignon piqué des clous de girofle, le céleri, les gousses d''ail écrasées, le poivre en grains et le sel. Laisser frémir à découvert deux heures, sans jamais laisser bouillir."},{"op":"replace","n":7,"instruction":"Servir le bouillon d''abord, puis la volaille découpée entourée des légumes, parsemée de persil ciselé."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
