  VALUES (v_version, 3, 'Garnir l''intérieur de la poule de cette farce, coudre l''ouverture et brider la volaille pour qu''elle garde sa forme pendant les trois heures de cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Déposer la poule dans une grande marmite, couvrir largement d''eau froide et porter lentement à frémissement. Écumer soigneusement pendant le premier quart d''heure : c''est ce qui donne un bouillon clair.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter l''oignon piqué des clous de girofle, le céleri, le poivre en grains et le sel. Laisser frémir à découvert deux heures, sans jamais laisser bouillir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Ajouter les carottes et les navets taillés en gros tronçons, puis les poireaux ficelés en botte trente minutes plus tard. Poursuivre jusqu''à ce que la cuisse se détache sans résistance.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Pendant ce temps, ôter les grosses côtes du chou vert et le tailler en larges lanières. Le plonger cinq minutes dans une grande casserole d''eau bouillante salée, l''égoutter, puis le laisser fondre vingt minutes dans deux louches de bouillon prélevées à la marmite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Servir le bouillon d''abord, puis la poule découpée et sa farce en tranches, entourée des légumes.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-001-D2', 'recipe_family', 'Poule au pot farcie au chou vert',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-001-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-001-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-001-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('4cf47eee4f974aed8017a812a2bef5ae'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":0,"heat":3,"pungency":0,"richness":2,"freshness":4,"intensity":1},"dominant_flavors":["bouillon_de_volaille","légumes_racines","farce_au_jambon"],"aroma_families":["volaille_pochée","légume_bouilli","muscade"],"target_textures":["chair_fondante","bouillon_clair","farce_moelleuse"],"signature_ingredients":["Poule crue","Pain de mie","Clou de girofle"],"identity_guardrails":["Le bouillon reste clair : on écume et on ne laisse jamais bouillir.","La poule est farcie — sans farce, c''est un pot-au-feu de volaille, pas une poule au pot."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
