         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-004-D2', 'recipe_family', 'Poulet vallée d''Auge aux poireaux',
                            'position', req.position, 'strictness', req.strictness),
