    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-005'), '{"variant_label":"Sans farce, en simple roulé de veau","rationale":"Sans farce, l''escalope n''est plus qu''un roulé : le plat perd le liant du porc haché et devient nettement plus maigre. La cuisson raccourcit d''autant, une paupiette pleine mettant plus longtemps à monter à cœur.","operations":[{"op":"remove","form":"Porc haché cru"},{"op":"set","form":"Escalope de veau crue fine","quantity":640}],"steps":[{"op":"replace","n":1,"instruction":"Étaler les escalopes entre deux feuilles de papier et les aplatir légèrement. Les saler, les poivrer, répartir dessus l''ail et le persil hachés, puis rouler et ficeler chaque roulé."},{"op":"replace","n":7,"instruction":"Retirer les ficelles et servir aussitôt, la sauce versée sur les roulés."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
