  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Détailler la dinde en cubes d''environ 4 cm. Émincer l''oignon, couper les carottes en rondelles épaisses, fendre le poireau dans la longueur, le rincer et le tronçonner. Dégermer et hacher l''ail. Brosser les champignons et les partager en quartiers.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire chauffer l''huile d''olive avec la moitié du beurre dans une cocotte à fond épais. Y déposer les cubes de dinde et les remuer sur feu moyen : ils doivent seulement blanchir et raidir, sans jamais prendre de couleur. Assaisonner de sel et de poivre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Ajouter l''oignon et l''ail, poursuivre deux à trois minutes toujours sans coloration, puis poudrer de farine. Remuer une minute pleine pour que la farine perde son goût cru et enrobe la viande.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser le vin blanc en grattant le fond à la spatule, laisser l''alcool s''évaporer une minute. Mouiller avec le bouillon et l''eau, ajouter le thym, les carottes et les poireaux, puis amener doucement au frémissement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Transvaser dans l''autocuiseur si la cocotte n''en est pas un, fermer et compter vingt-cinq minutes à partir de la mise en rotation de la soupape. Décompresser lentement plutôt que sous l''eau froide, pour que la viande ne se resserre pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Pendant la cuisson sous pression, saisir les champignons dans le beurre restant à feu vif jusqu''à ce que leur eau se soit évaporée et qu''ils brillent. Les réserver.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'À l''ouverture, verser les champignons dans la cocotte et les réchauffer une minute. Couper le feu, attendre que le bouillonnement cesse puis incorporer la crème. Si la sauce reste trop fluide, délayer la fécule dans deux cuillères de jus refroidi, l''ajouter et laisser épaissir deux minutes sans jamais faire bouillir. Rectifier l''assaisonnement et parsemer de persil ciselé au moment de servir.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-008-D2', 'recipe_family', 'Blanquette de dinde à l''autocuiseur',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-008-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-008-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-008-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('ba2ab8fde86650740c17697ea8d4ffc9'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":2,"salty":3,"acidic":1,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["volaille","crème","champignon"],"aroma_families":["lacté","herbacé","aillé"],"target_textures":["sauce nappante","viande fondante","légumes tendres"],"signature_ingredients":["Escalope de dinde crue","Crème fraîche liquide entière","Champignon de Paris frais"],"identity_guardrails":["La viande ne doit pas colorer : une dinde saisie brune donne un sauté en sauce brune, plus une blanquette.","Sans liaison crémée blanche (crème et farine), il ne reste qu''un bouillon de volaille aux légumes.","Pas de tomate ni de concentré de tomates : la sauce doit rester ivoire.","La crème s''incorpore hors ébullition, sinon elle tranche et la texture nappante est perdue."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Blanquette de dinde sans crème', 'blanquette de dinde sans creme', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Blanquette de dinde sans crème', 'Dinde pochée avec carottes, champignons et poireau dans un bouillon au vin blanc, sans liaison crémeuse', ds.id, 'SRC-008-D3',
    'Myko', 'editorial', 4, 25, 60, 'facile',
    NULL, NULL,
    'B', 'candidate', 'c5b31beac1d4a5365a32b73cb6ec8169',
    '{"sweet":2,"salty":3,"acidic":1,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['volaille','crème','champignon']::text[],
    ARRAY['lacté','herbacé','aillé']::text[], ARRAY['sauce nappante','viande fondante','légumes tendres']::text[],
    ARRAY['Escalope de dinde crue','Champignon de Paris frais']::text[], ARRAY['La viande ne doit pas colorer : une dinde saisie brune donne un sauté en sauce brune, plus une blanquette.','Sans liaison crémée blanche (crème et farine), il ne reste qu''un bouillon de volaille aux légumes.','Pas de tomate ni de concentré de tomates : la sauce doit rester ivoire.','La crème s''incorpore hors ébullition, sinon elle tranche et la texture nappante est perdue.']::text[],
    ARRAY['mijotage','déglaçage','réduction']::text[], ARRAY[]::text[], ARRAY['gluten','lait','sulfites']::text[],
    'Se garde 3 jours au réfrigérateur à 4 °C dans un contenant hermétique ; réchauffer à feu doux sans laisser bouillir pour que la sauce ne tranche pas. La congélation tient 2 mois mais uniquement sur la base non crémée (viande, légumes, bouillon lié) : la crème se rajoute après décongélation, sinon la sauce grène au réchauffage.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-008'), '{"variant_label":"Version allégée sans crème : remplacer la crème par un supplément de bouillon lié à la fécule de maïs.","rationale":"Sans crème la sauce perd son velouté et devient un jus lié, plus franc et nettement moins gras. La fécule cesse alors d''être un secours : elle est la seule liaison, et double de rôle.","operations":[{"op":"remove","form":"Crème fraîche liquide entière"},{"op":"set","form":"Bouillon de volaille","quantity":400},{"op":"set","form":"Fécule de maïs","quantity":25,"optional":false}],"steps":[{"op":"replace","n":7,"instruction":"Couper le feu et attendre que le bouillonnement cesse. Délayer la fécule dans quatre cuillères de jus refroidi, la reverser dans la cocotte et remuer sur feu doux deux minutes, jusqu''à ce que le jus nappe la cuillère sans jamais bouillir. Rectifier l''assaisonnement et parsemer de persil ciselé au moment de servir."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

