  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Faire tiedir 20 g de beurre doux a feu tres bas jusqu''a ce qu''il soit liquide mais encore blond, puis en badigeonner au pinceau une seule face de chacune des huit tranches de pain de mie.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Poser quatre tranches face beurree contre le plan de travail, repartir dessus la moitie de l''emmental rape, ajouter une tranche de jambon blanc cuit repliee pour epouser exactement le format du pain, puis saler et poivrer legerement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Recouvrir du reste d''emmental râpé. Découper au centre des quatre tranches restantes un disque de la taille d''un jaune à l''aide d''un verre, refermer avec elles face beurrée vers le haut et tasser d''un coup de paume pour que les couches adhèrent entre elles.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Chauffer une grande poele a feu moyen avec les 10 g de beurre doux restants, y coucher les croques et les laisser prendre couleur environ trois minutes par face, en pressant a la spatule pour que la chaleur atteigne le coeur et fasse fondre le fromage.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Retourner les croques dans la poêle, ouverture vers le haut. Casser un œuf dans chaque ouverture, assaisonner de sel fin et de poivre noir moulu, couvrir et laisser prendre trois à quatre minutes à feu doux : le blanc doit être figé, le jaune encore coulant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Parsemer le gruyère râpé sur les bords restés libres et glisser une minute sous le gril, le temps qu''il fonde sans que le jaune ne se raffermisse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Servir aussitôt, tant que le jaune coule encore à l''entaille.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-011-D2', 'recipe_family', 'Croque-madame à l''œuf encastré',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-011-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-011-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-011-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('73f2053dbc5d6b8bf175f0fb3ecbf84f'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":4,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":0,"intensity":3},"dominant_flavors":["fromage fondu","jambon sale","beurre dore"],"aroma_families":["lactee","grillee","beurree"],"target_textures":["pain grille croustillant","coeur fondant","jaune coulant"],"signature_ingredients":["Pain de mie","Œuf cru","Jambon blanc cuit","Emmental râpé"],"identity_guardrails":["Sans l''oeuf pose sur le dessus, le plat redevient un croque-monsieur et perd son nom.","Le pain de mie est la seule enveloppe admise : remplace par une baguette ou un pain de campagne, ce n''est plus un croque.","Le couple jambon blanc cuit et fromage fondu forme le coeur du plat ; retirer l''un des deux le denature."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Gratin de brocolis végétarien', 'gratin de brocolis vegetarien', 'France', 'France',
     'meal', 'gratin de légumes', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Gratin de brocolis végétarien', 'Brocolis blanchis gratinés dans une sauce béchamel crémeuse, sans protéine animale', ds.id, 'SRC-012-D1',
    'Myko', 'editorial', 4, 25, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', '9b9ca5546ef84e45faa9c5ed306b22f1',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":2,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['lacté','fromagé','végétal vert']::text[],
    ARRAY['lacté','alliacé','épicé doux']::text[], ARRAY['fondant','croûte gratinée croustillante','appareil pris']::text[],
    ARRAY['Brocoli cru','Lait entier','Gruyère râpé']::text[], ARRAY['Sans brocoli, le plat n''existe plus : c''est lui qui donne le nom, la couleur et la légère amertume végétale du gratin.','Sans liaison lactée à base de lait entier et de farine, on obtient des bouquets gratinés et non un gratin : la béchamel est ce qui lie le légume.','Sans couverture de gruyère râpé et de chapelure, il manque la croûte dorée qui définit le gratinage.','Le brocoli doit rester ferme et bien égoutté : trop cuit ou détrempé, il délave la sauce et fait rendre de l''eau au plat.']::text[],
    ARRAY['blanchiment','gratinage','réduction']::text[], ARRAY[]::text[], ARRAY['gluten','lait','œuf']::text[],
    'Se conserve 3 jours au réfrigérateur entre 0 et 4 °C, dans le plat filmé ou en boîte hermétique une fois refroidi à cœur. Réchauffer 15 à 20 minutes à 160 °C plutôt qu''au micro-ondes, pour retrouver la croûte. La congélation est déconseillée : l''appareil aux œufs et à la crème se dissocie en rendant de l''eau à la décongélation et le brocoli devient filandreux ; si on y tient, congeler avant cuisson au four, jusqu''à 1 mois à -18 °C, et enfourner sans décongeler en ajoutant 20 minutes.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-012'), '{"variant_label":"Version végétarienne : retirer le jambon blanc cuit et compenser en portant le gruyère râpé à 120 g pour garder du corps à l''appareil.","rationale":"Sans jambon, l''appareil perd son sel et sa mâche. Le gruyère majoré rend l''un et l''autre : le gratin reste un plat, il ne devient pas un accompagnement.","operations":[{"op":"remove","form":"Jambon blanc cuit"},{"op":"set","form":"Gruyère râpé","quantity":120}],"steps":[{"op":"replace","n":5,"instruction":"Battre les œufs à la fourchette dans un saladier. Y verser d''abord une louche de sauce tiédie en fouettant pour les tempérer, puis reverser le tout dans la casserole et mélanger. Incorporer la moitié du gruyère râpé ; goûter et rectifier l''assaisonnement à ce stade, la cuisson ne le corrigera plus."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

