  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Gratin de brocolis sans œuf', 'gratin de brocolis sans oeuf', 'France', 'France',
     'meal', 'gratin de légumes', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Gratin de brocolis sans œuf', 'Brocolis blanchis dans une béchamel crémeuse au jambon blanc, sans liant à l''œuf', ds.id, 'SRC-012-D4',
    'Myko', 'editorial', 4, 25, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', '771379690b692cf18a64b61c97ad0863',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":2,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['lacté','fromagé','végétal vert']::text[],
    ARRAY['lacté','alliacé','épicé doux']::text[], ARRAY['fondant','croûte gratinée croustillante','appareil pris']::text[],
    ARRAY['Brocoli cru','Lait entier','Gruyère râpé']::text[], ARRAY['Sans brocoli, le plat n''existe plus : c''est lui qui donne le nom, la couleur et la légère amertume végétale du gratin.','Sans liaison lactée à base de lait entier et de farine, on obtient des bouquets gratinés et non un gratin : la béchamel est ce qui lie le légume.','Sans couverture de gruyère râpé et de chapelure, il manque la croûte dorée qui définit le gratinage.','Le brocoli doit rester ferme et bien égoutté : trop cuit ou détrempé, il délave la sauce et fait rendre de l''eau au plat.']::text[],
    ARRAY['blanchiment','gratinage','réduction']::text[], ARRAY[]::text[], ARRAY['gluten','lait','œuf']::text[],
    'Se conserve 3 jours au réfrigérateur entre 0 et 4 °C, dans le plat filmé ou en boîte hermétique une fois refroidi à cœur. Réchauffer 15 à 20 minutes à 160 °C plutôt qu''au micro-ondes, pour retrouver la croûte. La congélation est déconseillée : l''appareil aux œufs et à la crème se dissocie en rendant de l''eau à la décongélation et le brocoli devient filandreux ; si on y tient, congeler avant cuisson au four, jusqu''à 1 mois à -18 °C, et enfourner sans décongeler en ajoutant 20 minutes.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-012'), '{"variant_label":"Sans œuf : omettre l''œuf cru et augmenter la farine de blé T55 à 50 g, ce qui donne un gratin plus coulant et moins compact.","rationale":"L''œuf prend à la chaleur et fige le gratin en une masse qui se découpe. Sans lui, seule la farine tient la sauce : le plat reste coulant, et se sert à la cuillère plutôt qu''à la spatule.","operations":[{"op":"remove","form":"Œuf cru"},{"op":"set","form":"Farine de blé T55","quantity":50}],"steps":[{"op":"replace","n":5,"instruction":"Incorporer à la sauce tiédie le jambon détaillé en petits dés et la moitié du gruyère râpé ; goûter et rectifier l''assaisonnement à ce stade, la cuisson ne le corrigera plus."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
