  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Rincer les lentilles sous l''eau froide dans une passoire fine jusqu''à ce que l''eau ressorte claire. Peler la carotte et la tailler en rondelles de 3 mm, fendre le poireau et le débiter en fines demi-rondelles après l''avoir bien lavé. Peler l''oignon et le couper en deux : une moitié partira entière à la cuisson, l''autre sera émincée crue au dernier moment.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Réunir dans une casserole les lentilles, la carotte, le poireau, la demi-moitié d''oignon entière, le laurier et le thym. Recouvrir de deux fois leur volume d''eau froide, sans sel : une eau salée dès le départ durcit la peau de la légumineuse et l''empêche de s''attendrir régulièrement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Monter doucement jusqu''au frémissement, puis baisser le feu au minimum et laisser cuire à découvert 12 à 15 minutes. La lentille corail se défait beaucoup plus vite que la verte : goûter dès la dixième minute et couper le feu à l''instant où le grain cède sous la dent tout en restant entier.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Saler seulement à ce moment-là, puis égoutter immédiatement et sans rincer pour stopper la cuisson. Retirer la moitié d''oignon et la feuille de laurier, garder carotte et poireau. Étaler le tout dans un saladier large : la chaleur retombe vite et les grains cessent de se coller entre eux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Pendant que les lentilles cuisent, plonger les œufs dans une casserole d''eau à petits bouillons et compter exactement 6 minutes pour un jaune encore coulant. Les basculer dans un bol d''eau glacée, attendre deux minutes, puis les écaler délicatement en commençant par le côté le plus large.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Dans un bol, écraser l''ail au presse-ail, ajouter le vinaigre de cidre, le poivre et une pincée de sel, puis verser l''huile d''olive en mince filet en fouettant sans arrêt jusqu''à ce que la sauce épaississe et cesse de se séparer. Verser sur les lentilles encore tièdes, mélanger à la spatule souple et laisser reposer 5 minutes : c''est en refroidissant qu''elles boivent la vinaigrette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Ciseler le persil et la ciboulette, concasser grossièrement les noix au couteau. Les ajouter au saladier avec l''oignon cru émincé très finement, mélanger une dernière fois, répartir dans les assiettes puis poser sur chacune un œuf ouvert en deux. Rectifier en poivre et servir sans attendre, à peine tiède.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-014-D2', 'recipe_family', 'Lentilles tièdes au vinaigre de cidre',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-014-D2', 'missing_required_count', v_missing), 'open');
  END IF;

