  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-015-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('7ba391540e137eb256790a6b0a4e4952'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":0,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":2,"intensity":2},"dominant_flavors":["jaune d''œuf cuit","mayonnaise","moutarde"],"aroma_families":["œuf cuit","moutardé","herbacé"],"target_textures":["blanc ferme et lisse","farce crémeuse","poudre sèche de jaune tamisé"],"signature_ingredients":["Œuf cru","Moutarde de Dijon"],"identity_guardrails":["La finition en jaune dur tamisé saupoudré sur le dessus est ce qui fait le mimosa : sans elle, le plat n''est qu''un œuf dur garni.","Les demi-blancs doivent rester entiers et servir de contenant ; hachés ou mixés, on bascule sur une salade d''œufs.","La liaison est une mayonnaise froide montée à l''huile, jamais une sauce cuite ni une crème chaude.","Le plat se sert froid, après passage au réfrigérateur ; tiède, la farce se délite et l''identité se perd."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
