  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-018-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('2dc49186e01f348772b1543cfee54e61'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":1,"salty":3,"acidic":3,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":1,"intensity":3},"dominant_flavors":["tomate cuite","iodé","aillé"],"aroma_families":["herbacé","aillé","fruité vert"],"target_textures":["pâtes al dente","sauce nappante","miettes de poisson fondantes"],"signature_ingredients":["Thon au naturel en conserve, égoutté","Tomate concassée en conserve","Petites pâtes sèches"],"identity_guardrails":["Le thon doit être ajouté en fin de cuisson et rester en miettes visibles : émietté trop tôt ou remué jusqu''à disparaître, le plat devient une simple sauce tomate.","La tomate concassée doit réduire avant l''arrivée du poisson : une sauce non réduite délave le plat et le rapproche d''un plat de pâtes à la sauce industrielle.","L''huile d''olive vierge extra est la seule matière grasse : remplacée par du beurre ou de la crème, le plat quitte son registre provençal."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
